import json, re
data = json.load(open('batches/batch_0056.json'))

def is_japanese_rich(s):
    if not s: return 0
    jp = sum(1 for c in s if ('぀'<=c<='ヿ') or ('一'<=c<='鿿'))
    return jp / max(len(s),1)

def try_all(s):
    variants = {'orig': s}
    try:
        variants['latin1->utf8'] = s.encode('latin1').decode('utf8')
    except Exception:
        pass
    try:
        variants['latin1->sjis'] = s.encode('latin1').decode('shift_jis')
    except Exception:
        pass
    try:
        variants['latin1->cp932'] = s.encode('latin1').decode('cp932')
    except Exception:
        pass
    # score each
    best_key, best_val, best_score = 'orig', s, is_japanese_rich(s)
    for k,v in variants.items():
        sc = is_japanese_rich(v)
        if sc > best_score:
            best_score = sc
            best_key = k
            best_val = v
    return best_key, best_val, best_score

out = []
for d in data:
    row = {'idx': d['idx'], 'name': d['name'], 'url': d['url'], 'ok': d['ok']}
    for field in ['title','desc','body']:
        s = d.get(field) or ''
        k,v,sc = try_all(s)
        row[field] = v
        row[field+'_method'] = k
        row[field+'_score'] = round(sc,2)
    out.append(row)

json.dump(out, open('batches/batch_0056_fixed.json','w'), ensure_ascii=False, indent=1)
for r in out:
    print(r['idx'], r['name'], '| body_method=', r['body_method'], 'score=', r['body_score'])
